(async () => {
  let state = await lf.ready;
  const appEl = document.getElementById('main-content');
  const previewNotice = document.getElementById('preview-notice');
  const tabDiscover = document.getElementById('tab-discover');
  const tabFavorites = document.getElementById('tab-favorites');
  const btnOpenAdd = document.getElementById('btn-open-add');

  if (state.preview) {
    previewNotice.style.display = 'block';
  }

  let currentTab = 'discover';
  let activeAsset = null;
  let captionText = '';

  tabDiscover.addEventListener('click', () => { currentTab = 'discover'; render(); });
  tabFavorites.addEventListener('click', () => { currentTab = 'favorites'; render(); });
  btnOpenAdd.addEventListener('click', () => { currentTab = 'add'; activeAsset = null; captionText = ''; render(); });

  lf.subscribe(next => {
    state = next;
    if (state.preview) previewNotice.style.display = 'block';
    render();
  });

  async function render() {
    tabDiscover.classList.toggle('active', currentTab === 'discover');
    tabFavorites.classList.toggle('active', currentTab === 'favorites');

    appEl.innerHTML = '';

    if (currentTab === 'add') {
      renderAddView(appEl);
      return;
    }

    const records = state.records || [];
    const pendingPhotos = records.filter(r => !r.values.decision);
    const favoritePhotos = records.filter(r => r.values.decision === 'favorite');

    if (currentTab === 'favorites') {
      renderFavoritesView(appEl, favoritePhotos);
      return;
    }

    if (pendingPhotos.length === 0) {
      renderEmptyState(appEl);
      return;
    }

    renderDiscoverView(appEl, pendingPhotos);
  }

  function renderAddView(container) {
    const wrapper = document.createElement('div');
    wrapper.className = 'add-card';

    const title = document.createElement('h2');
    title.textContent = 'Add a New Photo';
    wrapper.appendChild(title);

    const group = document.createElement('div');
    group.className = 'form-group';

    const label = document.createElement('label');
    label.textContent = 'Caption';
    label.setAttribute('for', 'caption-input');

    const input = document.createElement('input');
    input.id = 'caption-input';
    input.type = 'text';
    input.placeholder = 'A wonderful memory...';
    input.value = captionText;
    input.addEventListener('input', e => { captionText = e.target.value; });

    group.appendChild(label);
    group.appendChild(input);
    wrapper.appendChild(group);

    const pickBtn = document.createElement('button');
    pickBtn.className = 'btn btn-secondary';
    pickBtn.textContent = activeAsset ? 'Photo Selected ✓' : 'Pick Photo from Device';
    pickBtn.addEventListener('click', async () => {
      try {
        const res = await lf.pickImage();
        if (res && res.assetId) {
          activeAsset = res.assetId;
          pickBtn.textContent = 'Photo Selected ✓';
        }
      } catch (err) {
        console.error(err);
      }
    });
    wrapper.appendChild(pickBtn);

    const submitBtn = document.createElement('button');
    submitBtn.className = 'btn';
    submitBtn.textContent = 'Save Photo';
    submitBtn.addEventListener('click', async () => {
      if (!activeAsset) {
        alert('Please pick a photo first.');
        return;
      }
      try {
        state = await lf.create({
          caption: captionText || 'Untitled',
          assetId: activeAsset,
          decision: ''
        });
        currentTab = 'discover';
        render();
      } catch (err) {
        alert('Failed to save photo: ' + err.message);
      }
    });
    wrapper.appendChild(submitBtn);

    container.appendChild(wrapper);
  }

  function renderEmptyState(container) {
    const empty = document.createElement('div');
    empty.className = 'empty-state';

    const h3 = document.createElement('h3');
    h3.textContent = 'Add your first photo';
    const p = document.createElement('p');
    p.textContent = 'Discover and curate your personal photo collection by adding memories today.';

    const btn = document.createElement('button');
    btn.className = 'btn';
    btn.textContent = 'Add Photo';
    btn.addEventListener('click', () => { currentTab = 'add'; activeAsset = null; captionText = ''; render(); });

    empty.appendChild(h3);
    empty.appendChild(p);
    empty.appendChild(btn);
    container.appendChild(empty);
  }

  function renderFavoritesView(container, favs) {
    if (favs.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'empty-state';
      const h3 = document.createElement('h3');
      h3.textContent = 'No favorites yet';
      const p = document.createElement('p');
      p.textContent = 'Swipe right on photos in Discover to save them here.';
      empty.appendChild(h3);
      empty.appendChild(p);
      container.appendChild(empty);
      return;
    }

    const grid = document.createElement('div');
    grid.className = 'favorites-grid';

    for (const rec of favs) {
      const card = document.createElement('div');
      card.className = 'fav-card';

      const img = document.createElement('img');
      img.alt = rec.values.caption || 'Favorite photo';
      lf.image(rec.values.assetId).then(res => {
        if (res && res.dataUrl) img.src = res.dataUrl;
      }).catch(() => {});

      const p = document.createElement('p');
      p.textContent = rec.values.caption;

      card.appendChild(img);
      card.appendChild(p);
      grid.appendChild(card);
    }
    container.appendChild(grid);
  }

  function renderDiscoverView(container, pending) {
    const deck = document.createElement('div');
    deck.className = 'deck-container';

    const currentRec = pending[0];
    const card = document.createElement('div');
    card.className = 'photo-card';

    const img = document.createElement('img');
    img.alt = currentRec.values.caption || 'Photo';
    img.draggable = false;
    lf.image(currentRec.values.assetId).then(res => {
      if (res && res.dataUrl) img.src = res.dataUrl;
    }).catch(() => {});

    const info = document.createElement('div');
    info.className = 'photo-info';
    const cap = document.createElement('div');
    cap.className = 'photo-caption';
    cap.textContent = currentRec.values.caption;
    info.appendChild(cap);

    card.appendChild(img);
    card.appendChild(info);
    deck.appendChild(card);

    const actionBar = document.createElement('div');
    actionBar.className = 'action-bar';

    const passBtn = document.createElement('button');
    passBtn.className = 'circle-btn pass';
    passBtn.textContent = '✕';
    passBtn.setAttribute('aria-label', 'Pass');
    passBtn.addEventListener('click', () => handleDecision(currentRec.id, 'pass', card));

    const favBtn = document.createElement('button');
    favBtn.className = 'circle-btn fav';
    favBtn.textContent = '♥';
    favBtn.setAttribute('aria-label', 'Favorite');
    favBtn.addEventListener('click', () => handleDecision(currentRec.id, 'favorite', card));

    actionBar.appendChild(passBtn);
    actionBar.appendChild(favBtn);

    const wrapper = document.createElement('div');
    wrapper.style.display = 'flex';
    wrapper.style.flexDirection = 'column';
    wrapper.style.width = '100%';
    wrapper.appendChild(deck);
    wrapper.appendChild(actionBar);

    container.appendChild(wrapper);

    let startX = 0;
    let currentX = 0;
    let isDragging = false;

    card.addEventListener('pointerdown', e => {
      isDragging = true;
      startX = e.clientX;
      card.setPointerCapture(e.pointerId);
    });

    card.addEventListener('pointermove', e => {
      if (!isDragging) return;
      currentX = e.clientX - startX;
      card.style.transform = `translateX(${currentX}px) rotate(${currentX * 0.05}deg)`;
    });

    card.addEventListener('pointerup', e => {
      if (!isDragging) return;
      isDragging = false;
      try {
        card.releasePointerCapture(e.pointerId);
      } catch (err) {}
      if (currentX > 100) {
        handleDecision(currentRec.id, 'favorite', card);
      } else if (currentX < -100) {
        handleDecision(currentRec.id, 'pass', card);
      } else {
        card.style.transform = 'translateX(0px) rotate(0deg)';
      }
      currentX = 0;
    });
  }

  async function handleDecision(id, decision, cardEl) {
    if (cardEl) {
      cardEl.style.transform = decision === 'favorite' ? 'translateX(400px) rotate(20deg)' : 'translateX(-400px) rotate(-20deg)';
      cardEl.style.opacity = '0';
    }
    try {
      state = await lf.update(id, { decision });
      setTimeout(render, 200);
    } catch (err) {
      alert('Failed to update decision: ' + err.message);
      render();
    }
  }

  render();
  await lf.reportReady();
})();

